begin;
update public.listings set images=array(select 'https://images.unsplash.com/photo-'||x||'?w=1200&q=80&auto=format&fit=crop' from unnest(images) x);
select l.id, (array['Emma','James','Olivia','Lucas','Mia','Ethan','Ava','Leo','Zoe','Daniel','Nora','Sam','Lily','Max','Grace','Ben','Hannah','Adam'])[1+floor(random()*18)::int],
 case when random()<0.7 then 'https://i.pravatar.cc/150?img='||(1+floor(random()*70)::int) end,
 (array[5,5,5,4,4,3])[1+floor(random()*6)::int],
 (array['Absolutely stunning place, even better than the photos.','The host was incredibly responsive and helpful. Would stay again!','Perfect location and spotless throughout.','Beautiful home with everything we needed. Highly recommend.','Great stay overall, though the wifi was a little slow.','One of the best places we have ever stayed. Magical views.','Cozy, quiet and very comfortable beds.','Check-in was seamless and the space was thoughtfully equipped.','Lovely spot for a relaxing getaway. A few minor wear and tear issues.','We did not want to leave. Already planning our return.'])[1+floor(random()*10)::int],
 now()-((5+floor(random()*400))::int||' days')::interval
from public.listings l cross join lateral generate_series(1,3+floor(random()*4)::int + (0*length(l.title))) g;
update public.listings l set rating=s.avg, review_count=s.cnt from (select listing_id, round(avg(rating)::numeric,2) avg, count(*) cnt from public.reviews group by listing_id) s where s.listing_id=l.id;
commit;